func TestDecodeJsonWebToken(t *testing.T) {
	// Valid token and key
	validToken := "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJuYW1lIjoiSm9obiBEb2UiLCJleHAiOjE2MjMyNDQwMDB9"
	validKey := "secretkey"
	result := decodeJsonWebToken(validToken, validKey)
	if result != "{\"name\":\"John Doe\",\"exp\":1623244007}" {
		t.Errorf("Expected valid token to return claims, but got %s", result)
	}

	// Invalid token
	invalidToken := "invalid.token"
	result = decodeJsonWebToken(invalidToken, validKey)
	if result != "{}" {
		t.Errorf("Expected invalid token to return empty JSON object, but got %s", result)
	}

	// Correct token with wrong key
	wrongKey := "wrongsecretkey"
	result = decodeJsonWebToken(validToken, wrongKey)
	if result != "{}" {
		t.Errorf("Expected correct token with wrong key to return empty JSON object, but got %s", result)
	}

	// Empty token
	emptyToken := ""
	result = decodeJsonWebToken(emptyToken, validKey)
	if result != "{}" {
		t.Errorf("Expected empty token to return empty JSON object, but got %s", result)
	}
}

